(()=>{const root=document.querySelector('.instrument-library');if(!root)return;const search=root.querySelector('#instrument-search'),cards=[...root.querySelectorAll('.instrument-card')],buttons=[...root.querySelectorAll('[data-filter]')];let family='all';const normalize=s=>s.replace(/ي/g,'ی').replace(/ك/g,'ک').replace(/[\s\u200c/-]/g,'').toLowerCase();function apply(){const query=normalize(search.value);let count=0;for(const c of cards){const show=(family==='all'||c.dataset.family===family)&&normalize(c.dataset.name).includes(query);c.hidden=!show;if(show)count++}root.querySelector('#instrument-results').textContent=count.toLocaleString('fa-IR')+' ساز و مسیر آموزشی';root.querySelector('#instrument-empty').hidden=count!==0}search.addEventListener('input',apply);buttons.forEach(b=>b.addEventListener('click',()=>{family=b.dataset.filter;buttons.forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply()}))})();
